import { agentNativePath } from "../api-path.js";
export function workspaceProviderOAuthUrl(provider, options) {
    const params = new URLSearchParams({
        appId: options.appId,
        scope: options.scope ?? "user",
    });
    if (options.returnPath)
        params.set("return", options.returnPath);
    return agentNativePath(`/_agent-native/connections/oauth/${provider}/start?${params.toString()}`);
}
export function startWorkspaceProviderOAuth(provider, options) {
    window.location.assign(workspaceProviderOAuthUrl(provider, options));
}
